@Override
public void process(Operator operator, List<COSBase> operands) throws IOException // PATH: Test should invoke the next PageDrawer.shadingFill(...) [step in execution path]
{
    if (operands.isEmpty()) {
        throw new MissingOperandException(operator, operands);
    }
    COSBase base = operands.get(0);
    if (!(base instanceof COSName)) {
        throw new MissingOperandException(operator, operands);
    }
    getGraphicsContext().shadingFill(((COSName) (base)));
}

@Override
public void shadingFill(COSName shadingName) throws IOException {
    if (!isContentRendered()) {
        return;
    }
    PDShading shading = getResources().getShading(shadingName);
    if (shading == null) {
        LOG.error(("shading " + shadingName) + " does not exist in resources dictionary");
        return;
    }
    Matrix ctm = getGraphicsState().getCurrentTransformationMatrix();
    graphics.setComposite(getGraphicsState().getNonStrokingJavaComposite());
    Shape savedClip = graphics.getClip();
    graphics.setClip(null);
    lastClips = null;
    // get the transformed BBox and intersect with current clipping path
    // need to do it here and not in shading getRaster() because it may have been rotated
    PDRectangle bbox = shading.getBBox();
    Area area;
    if (bbox != null) {
        area = new Area(bbox.transform(ctm));
        area.intersect(getGraphicsState().getCurrentClippingPath());
    } else {
        // PATH: Test should invoke the next PDShadingType5.getBounds(...) [step in execution path]
        Rectangle2D bounds = shading.getBounds(new AffineTransform(), ctm);
        if (bounds != null) {
            bounds.add(new Point2D.Double(Math.floor(bounds.getMinX() - 1), Math.floor(bounds.getMinY() - 1)));
            bounds.add(new Point2D.Double(Math.ceil(bounds.getMaxX() + 1), Math.ceil(bounds.getMaxY() + 1)));
            area = new Area(bounds);
            area.intersect(getGraphicsState().getCurrentClippingPath());
        } else {
            area = getGraphicsState().getCurrentClippingPath();
        }
    }
    if (!area.isEmpty()) {
        // creating Paint is sometimes a costly operation, so avoid if possible
        Paint paint = shading.toPaint(ctm);
        paint = applySoftMaskToPaint(paint, getGraphicsState().getSoftMask());
        graphics.setPaint(paint);
        graphics.fill(area);
    }
    graphics.setClip(savedClip);
}

@Override
public Rectangle2D getBounds(AffineTransform xform, Matrix matrix) throws IOException {
    Rectangle2D bounds = null;
    // PATH: Test should invoke the next PDShadingType4.collectTriangles(...) [step in execution path]
    for (ShadedTriangle shadedTriangle : collectTriangles(xform, matrix)) {
        if (bounds == null) {
            bounds = new Rectangle2D.Double(shadedTriangle.corner[0].getX(), shadedTriangle.corner[0].getY(), 0, 0);
        }
        bounds.add(shadedTriangle.corner[0]);
        bounds.add(shadedTriangle.corner[1]);
        bounds.add(shadedTriangle.corner[2]);
    }
    if (bounds == null) {
        // Speeds up files where triangles are empty, e.g. ghostscript file 690425
        return new Rectangle2D.Float();
    }
    return bounds;
}

@SuppressWarnings("squid:S1166")
@Override
List<ShadedTriangle> collectTriangles(AffineTransform xform, Matrix matrix) throws IOException {
    int bitsPerFlag = getBitsPerFlag();
    COSDictionary dict = getCOSObject();
    if (!(dict instanceof COSStream)) {
        return Collections.emptyList();
    }
    PDRange rangeX = getDecodeForParameter(0);
    PDRange rangeY = getDecodeForParameter(1);
    if ((((rangeX == null) || (rangeY == null)) || (Float.compare(rangeX.getMin(), rangeX.getMax()) == 0)) || (Float.compare(rangeY.getMin(), rangeY.getMax()) == 0)) {
        return Collections.emptyList();
    }
    PDRange[] colRange = new PDRange[getNumberOfColorComponents()];
    for (int i = 0; i < colRange.length; ++i) {
        colRange[i] = getDecodeForParameter(2 + i);
        if (colRange[i] == null) {
            throw new IOException("Range missing in shading /Decode entry");
        }
    }
    List<ShadedTriangle> list = new ArrayList<>();
    long maxSrcCoord = // PATH: Test should invoke the next PDShadingType4.getBitsPerCoordinate(...) [step in execution path]
    ((long) (Math.pow(2, getBitsPerCoordinate()))) - 1;
    long maxSrcColor = ((long) (Math.pow(2, getBitsPerComponent()))) - 1;
    // MemoryCacheImageInputStream doesn't close the wrapped stream
    try (InputStream imageStream = ((COSStream) (dict)).createInputStream()) {
        try (ImageInputStream mciis = new MemoryCacheImageInputStream(imageStream)) {
            byte flag = ((byte) (0));
            try {
                flag = ((byte) (mciis.readBits(bitsPerFlag) & 3));
            } catch (EOFException ex) {
                LOG.error(ex);
            }
            boolean eof = false;
            while (!eof) {
                Vertex p0;
                Vertex p1;
                Vertex p2;
                Point2D[] ps;
                float[][] cs;
                int lastIndex;
                try {
                    switch (flag) {
                        case 0 :
                            p0 = readVertex(mciis, maxSrcCoord, maxSrcColor, rangeX, rangeY, colRange, matrix, xform);
                            flag = ((byte) (mciis.readBits(bitsPerFlag) & 3));
                            if (flag != 0) {
                                LOG.error("bad triangle: " + flag);
                            }
                            p1 = readVertex(mciis, maxSrcCoord, maxSrcColor, rangeX, rangeY, colRange, matrix, xform);
                            mciis.readBits(bitsPerFlag);
                            if (flag != 0) {
                                LOG.error("bad triangle: " + flag);
                            }
                            p2 = readVertex(mciis, maxSrcCoord, maxSrcColor, rangeX, rangeY, colRange, matrix, xform);
                            ps = new Point2D[]{ p0.point, p1.point, p2.point };
                            cs = new float[][]{ p0.color, p1.color, p2.color };
                            list.add(new ShadedTriangle(ps, cs));
                            flag = ((byte) (mciis.readBits(bitsPerFlag) & 3));
                            break;
                        case 1 :
                        case 2 :
                            lastIndex = list.size() - 1;
                            if (lastIndex < 0) {
                                LOG.error(("broken data stream: " + list.size()) + ", aborting");
                                eof = true;
                            } else {
                                ShadedTriangle preTri = list.get(lastIndex);
                                p2 = readVertex(mciis, maxSrcCoord, maxSrcColor, rangeX, rangeY, colRange, matrix, xform);
                                ps = new Point2D[]{ flag == 1 ? preTri.corner[1] : preTri.corner[0], preTri.corner[2], p2.point };
                                cs = new float[][]{ flag == 1 ? preTri.color[1] : preTri.color[0], preTri.color[2], p2.color };
                                list.add(new ShadedTriangle(ps, cs));
                                flag = ((byte) (mciis.readBits(bitsPerFlag) & 3));
                            }
                            break;
                        default :
                            LOG.error(("bad flag " + flag) + ", aborting");
                            eof = true;
                            break;
                    }
                } catch (EOFException ex) {
                    eof = true;
                }
            } 
        }
    }
    return list;
}

/**
 * The bits per coordinate of this shading. This will return -1 if one has
 * not been set.
 *
 * @return the number of bits per coordinate
 */
public int getBitsPerCoordinate() {
    if (bitsPerCoordinate == (-1)) {
        bitsPerCoordinate = getCOSObject().getInt(COSName.BITS_PER_COORDINATE, -1);
        // PATH: Test should invoke the next Log.isDebugEnabled(...) [step in execution path]
        if (LOG.isDebugEnabled()) {
            LOG.debug("bitsPerCoordinate: " + (Math.pow(2, bitsPerCoordinate) - 1));
        }
    }
    return bitsPerCoordinate;
}

