/**
 * Creates a new TrueType font from a Font dictionary.
 *
 * @param fontDictionary
 * 		The font dictionary according to the PDF specification.
 * @throws IOException
 * 		if the font could not be created
 */
public PDTrueTypeFont(COSDictionary fontDictionary) throws IOException {
    super(fontDictionary);
    TrueTypeFont ttfFont = null;
    boolean fontIsDamaged = false;
    if (getFontDescriptor() != null) {
        PDFontDescriptor fd = super.getFontDescriptor();
        PDStream ff2Stream = fd.getFontFile2();
        if (ff2Stream != null) {
            RandomAccessRead view = null;
            try {
                view = ff2Stream.getCOSObject().createView();
                // embedded
                TTFParser ttfParser = getParser(view, true);
                ttfFont = ttfParser.parse(view);
                ttfFont.close();
            } catch (IOException e) {
                LOG.warn("Could not read embedded TTF for font " + getBaseFont(), e);
                fontIsDamaged = true;
                IOUtils.closeQuietly(view);
            }
        }
    }
    isEmbedded = ttfFont != null;
    isDamaged = fontIsDamaged;
    // substitute
    if (ttfFont == null) {
        FontMapping<TrueTypeFont> mapping = FontMappers.instance().getTrueTypeFont(getBaseFont(), getFontDescriptor());
        ttfFont = mapping.getFont();
        if (mapping.isFallback()) {
            LOG.warn((("Using fallback font " + ttfFont) + " for ") + getBaseFont());
        }
    }
    otf = ((ttfFont instanceof OpenTypeFont) && ((OpenTypeFont) (ttfFont)).isSupportedOTF()) ? ((OpenTypeFont) (ttfFont)) : null;
    ttf = ttfFont;
    readEncoding();
}

/**
 * Creates a new TrueType font for embedding.
 */
private PDTrueTypeFont(PDDocument document, TrueTypeFont ttf, Encoding encoding, boolean closeTTF) throws IOException {
    PDTrueTypeFontEmbedder embedder = new PDTrueTypeFontEmbedder(document, dict, ttf, encoding);
    this.encoding = encoding;
    this.ttf = ttf;
    // OpenTypeFonts are not fully supported yet
    otf = null;
    setFontDescriptor(embedder.getFontDescriptor());
    isEmbedded = true;
    isDamaged = false;
    glyphList = GlyphList.getAdobeGlyphList();
    if (closeTTF) {
        // the TTF is fully loaded and it is safe to close the underlying data source
        ttf.close();
    }
}

