/**
 * Get the documents AcroForm. This will return null if no AcroForm is part of the document.
 *
 * Dependent on setting <code>acroFormFixup</code> some fixing/changes will be done to the AcroForm.
 * If you need to ensure that there are no fixes applied call <code>getAcroForm</code> with <code>null</code>.
 *
 * Using <code>getAcroForm(PDDocumentFixup acroFormFixup)</code> might change the original content and
 * subsequent calls with <code>getAcroForm(null)</code> will return the changed content.
 *
 * @param acroFormFixup
 * 		the fix up action or null
 * @return The document's AcroForm.
 */
public PDAcroForm getAcroForm(PDDocumentFixup acroFormFixup) {
    if ((acroFormFixup != null) && (acroFormFixup != acroFormFixupApplied)) // PATH: Test should invoke the next AcroFormDefaultFixup.apply(...) [step in execution path]
    {
        acroFormFixup.apply();
        cachedAcroForm = null;
        acroFormFixupApplied = acroFormFixup;
    } else if (acroFormFixupApplied != null) {
        LOG.debug("AcroForm content has already been retrieved with fixes applied - original content changed because of that");
    }
    if (cachedAcroForm == null) {
        COSDictionary dict = root.getCOSDictionary(COSName.ACRO_FORM);
        cachedAcroForm = (dict == null) ? null : new PDAcroForm(document, dict);
    }
    return cachedAcroForm;
}

@Override
public void apply() {
    new AcroFormDefaultsProcessor(document).process();
    /* Get the AcroForm in it's current state.

    Also note: getAcroForm() applies a default fixup which this processor
    is part of. So keep the null parameter otherwise this will end
    in an endless recursive call
     */
    PDAcroForm acroForm = document.getDocumentCatalog().getAcroForm(null);
    // PDFBOX-4985
    // build the visual appearance as there is none for the widgets
    if ((acroForm != null) && acroForm.getNeedAppearances()) {
        if (acroForm.getFields().isEmpty()) // PATH: Test should invoke the next AcroFormOrphanWidgetsProcessor.process(...) [step in execution path]
        {
            new AcroFormOrphanWidgetsProcessor(document).process();
        }
        // PDFBOX-4985
        // build the visual appearance as there is none for the widgets
        new AcroFormGenerateAppearancesProcessor(document).process();
    }
}

@Override
public void process() {
    /* Get the AcroForm in it's current state.

    Also note: getAcroForm() applies a default fixup which this processor
    is part of. So keep the null parameter otherwise this will end
    in an endless recursive call
     */
    PDAcroForm acroForm = document.getDocumentCatalog().getAcroForm(null);
    if (acroForm != null) // PATH: Test should invoke the next AcroFormOrphanWidgetsProcessor.resolveFieldsFromWidgets(...) [step in execution path]
    {
        resolveFieldsFromWidgets(acroForm);
    }
}

private void resolveFieldsFromWidgets(PDAcroForm acroForm) {
    LOG.debug("rebuilding fields from widgets");
    PDResources resources = acroForm.getDefaultResources();
    if (resources == null) {
        // failsafe. Currently resources is never null because defaultfixup is called first.
        LOG.debug("AcroForm default resources is null");
        return;
    }
    List<PDField> fields = new ArrayList<>();
    Map<String, PDField> nonTerminalFieldsMap = new HashMap<>();
    for (PDPage page : document.getPages()) {
        try {
            handleAnnotations(acroForm, resources, fields, page.getAnnotations(), nonTerminalFieldsMap);
        } catch (IOException ioe) {
            LOG.debug("couldn't read annotations for page " + ioe.getMessage());
        }
    }
    acroForm.setFields(fields);
    for (PDField field : acroForm.getFieldTree()) {
        if (field instanceof PDVariableText) // PATH: Test should invoke the next AcroFormOrphanWidgetsProcessor.ensureFontResources(...) [step in execution path]
        {
            ensureFontResources(resources, ((PDVariableText) (field)));
        }
    }
}

/* Lookup the font used in the default appearance and if this is 
not available try to find a suitable font and use that.
This may not be the original font but a similar font replacement

TODO: implement a font lookup similar as discussed in PDFBOX-2661 so that already existing
font resources might be accepatble.
In such case this must be implemented in PDDefaultAppearanceString too!
 */
private void ensureFontResources(PDResources defaultResources, PDVariableText field) {
    String daString = field.getDefaultAppearance();
    if (daString.startsWith("/") && (daString.length() > 1)) {
        COSName fontName = COSName.getPDFName(daString.substring(1, daString.indexOf(" ")));
        try {
            // PATH: Test should invoke the next PDResources.getFont(...) [step in execution path]
            if (defaultResources.getFont(fontName) == null) {
                if (LOG.isDebugEnabled()) {
                    LOG.debug("trying to add missing font resource for field " + field.getFullyQualifiedName());
                }
                FontMapper mapper = FontMappers.instance();
                FontMapping<TrueTypeFont> fontMapping = mapper.getTrueTypeFont(fontName.getName(), null);
                if (fontMapping != null) {
                    PDType0Font pdFont = PDType0Font.load(document, fontMapping.getFont(), false);
                    if (LOG.isDebugEnabled()) {
                        LOG.debug((("looked up font for " + fontName.getName()) + " - found ") + fontMapping.getFont().getName());
                    }
                    defaultResources.put(fontName, pdFont);
                } else if (LOG.isDebugEnabled()) {
                    LOG.debug((("no suitable font found for field " + field.getFullyQualifiedName()) + " for font name ") + fontName.getName());
                }
            }
        } catch (IOException ioe) {
            LOG.debug((("unable to handle font resources for field " + field.getFullyQualifiedName()) + ": ") + ioe.getMessage());
        }
    }
}

/**
 * Returns the font resource with the given name, or null if none exists.
 *
 * @param name
 * 		Name of the font resource.
 * @return the font with the given name or null
 * @throws IOException
 * 		if something went wrong.
 */
public PDFont getFont(COSName name) throws IOException {
    COSObject indirect = getIndirect(COSName.FONT, name);
    if ((cache != null) && (indirect != null)) {
        PDFont cached = cache.getFont(indirect);
        if (cached != null) {
            return cached;
        }
    } else if (indirect == null) {
        SoftReference<PDFont> ref = directFontCache.get(name);
        if (ref != null) {
            PDFont cached = ref.get();
            if (cached != null) {
                return cached;
            }
        }
    }
    PDFont font = null;
    COSBase base = get(COSName.FONT, name);
    if (base instanceof COSDictionary) {
        // PATH: Test should invoke the next PDFontFactory.createFont(...) [step in execution path]
        font = PDFontFactory.createFont(((COSDictionary) (base)), cache);
    }
    if ((cache != null) && (indirect != null)) {
        cache.put(indirect, font);
    } else if (indirect == null) {
        directFontCache.put(name, new SoftReference<>(font));
    }
    return font;
}

/**
 * Creates a new PDFont instance with the appropriate subclass.
 *
 * @param dictionary
 * 		a font dictionary
 * @param resourceCache
 * 		resource cache, only useful for type 3 fonts, can be null
 * @return a PDFont instance, based on the SubType entry of the dictionary
 * @throws IOException
 * 		if something goes wrong
 */
public static PDFont createFont(COSDictionary dictionary, ResourceCache resourceCache) throws IOException {
    COSName type = dictionary.getCOSName(COSName.TYPE, COSName.FONT);
    if (!COSName.FONT.equals(type)) {
        LOG.error(("Expected 'Font' dictionary but found '" + type.getName()) + "'");
    }
    COSName subType = dictionary.getCOSName(COSName.SUBTYPE);
    if (COSName.TYPE1.equals(subType)) {
        COSDictionary fd = dictionary.getCOSDictionary(COSName.FONT_DESC);
        if ((fd != null) && fd.containsKey(COSName.FONT_FILE3)) {
            return new PDType1CFont(dictionary);
        }
        return new PDType1Font(dictionary);
    } else if (COSName.MM_TYPE1.equals(subType)) {
        COSDictionary fd = dictionary.getCOSDictionary(COSName.FONT_DESC);
        if ((fd != null) && fd.containsKey(COSName.FONT_FILE3)) {
            return new PDType1CFont(dictionary);
        }
        return new PDMMType1Font(dictionary);
    } else if (COSName.TRUE_TYPE.equals(subType)) {
        return new PDTrueTypeFont(dictionary);
    } else if (COSName.TYPE3.equals(subType)) {
        return new PDType3Font(dictionary, resourceCache);
    } else if (COSName.TYPE0.equals(subType)) {
        COSDictionary fontDescriptor = getFontDescriptor(dictionary);
        FontType fontTypeFromFont = getFontTypeFromFont(fontDescriptor, subType);
        if (fontTypeFromFont != null) {
            COSDictionary descendantFont = getDescendantFont(dictionary);
            COSName descFontType = (descendantFont != null) ? descendantFont.getCOSName(COSName.SUBTYPE) : null;
            if ((descFontType != null) && (!fontTypeFromFont.isCIDSubtype(descFontType))) {
                fixType0Subtype(descendantFont, fontDescriptor, fontTypeFromFont.getSubtype());
            }
        }
        return new PDType0Font(dictionary);
    } else if (COSName.CID_FONT_TYPE0.equals(subType)) {
        throw new IOException("Type 0 descendant font not allowed");
    } else if (COSName.CID_FONT_TYPE2.equals(subType)) {
        throw new IOException("Type 2 descendant font not allowed");
    } else {
        // assuming Type 1 font (see PDFBOX-1988) because it seems that Adobe Reader does this
        // however, we may need more sophisticated logic perhaps looking at the FontFile
        LOG.warn(("Invalid font subtype '" + subType) + "'");
        return new PDType1Font(dictionary);
    }
}

