/**
 * Constructor.
 *
 * @param fontDictionary
 * 		The font dictionary according to the PDF specification.
 * @param parent
 * 		The parent font.
 * @throws IOException
 * 		if the font could not be read
 */
public (COSDictionary fontDictionary, PDType0Font parent) throws IOException {
    this(fontDictionary, parent);
    boolean fontIsDamaged = false;
    CFFFont cffFont = null;
    PDFontDescriptor fd = getFontDescriptor();
    if (fd != null) {
        PDStream ff3Stream = fd.getFontFile3();
        if (ff3Stream != null) {
            try (RandomAccessRead randomAccessRead = ff3Stream.getCOSObject().createView()) {
                if ((randomAccessRead.length() > 0) && (randomAccessRead.peek() == '%')) {
                    // PDFBOX-2642 contains a corrupt PFB font instead of a CFF
                    LOG.warn("Found PFB but expected embedded CFF font " + fd.getFontName());
                    fontIsDamaged = true;
                } else {
                    CFFParser cffParser = new CFFParser();
                    cffFont = cffParser.parse(randomAccessRead).get(0);
                }
            } catch (IOException e) {
                LOG.error("Can't read the embedded CFF font " + fd.getFontName(), e);
                fontIsDamaged = true;
            }
        }
    }
    if (cffFont != null) {
        // embedded
        if (cffFont instanceof CFFCIDFont) {
            cidFont = ((CFFCIDFont) (cffFont));
            t1Font = null;
        } else {
            cidFont = null;
            t1Font = cffFont;
        }
        cid2gid = readCIDToGIDMap();
        isEmbedded = true;
        isDamaged = false;
    } else {
        // find font or substitute
        // PATH: Test should invoke the next FontMapperImpl.getCIDFont(...) [step in execution path]
        CIDFontMapping mapping = FontMappers.instance().getCIDFont(getBaseFont(), getFontDescriptor(), getCIDSystemInfo());
        FontBoxFont font;
        if (mapping.isCIDFont()) {
            cffFont = mapping.getFont().getCFF().getFont();
            if (cffFont instanceof CFFCIDFont) {
                cidFont = ((CFFCIDFont) (cffFont));
                t1Font = null;
                font = cidFont;
            } else {
                // PDFBOX-3515: OpenType fonts are loaded as CFFType1Font
                CFFType1Font f = ((CFFType1Font) (cffFont));
                cidFont = null;
                t1Font = f;
                font = f;
            }
        } else {
            cidFont = null;
            t1Font = mapping.getTrueTypeFont();
            font = t1Font;
        }
        if (mapping.isFallback()) {
            LOG.warn((("Using fallback " + font.getName()) + " for CID-keyed font ") + getBaseFont());
        }
        isEmbedded = false;
        isDamaged = fontIsDamaged;
    }
    fontMatrixTransform = getFontMatrix().createAffineTransform();
    fontMatrixTransform.scale(1000, 1000);
}

/**
 * Finds a CFF CID-Keyed font with the given PostScript name, or a suitable substitute, or null.
 * This method can also map CJK fonts via their CIDSystemInfo (ROS).
 *
 * @param fontDescriptor
 * 		FontDescriptor
 * @param cidSystemInfo
 * 		the CID system info, e.g. "Adobe-Japan1", if any.
 */
@Override
public CIDFontMapping getCIDFont(String baseFont, PDFontDescriptor fontDescriptor, PDCIDSystemInfo cidSystemInfo) {
    // try name match or substitute with OTF
    // PATH: Test should invoke the next FontMapperImpl.findFont(...) [step in execution path]
    OpenTypeFont otf1 = ((OpenTypeFont) (findFont(FontFormat.OTF, baseFont)));
    if (otf1 != null) {
        return new CIDFontMapping(otf1, null, false);
    }
    // try name match or substitute with TTF
    TrueTypeFont ttf = ((TrueTypeFont) (findFont(FontFormat.TTF, baseFont)));
    if (ttf != null) {
        return new CIDFontMapping(null, ttf, false);
    }
    if (cidSystemInfo != null) {
        // "In Acrobat 3.0.1 and later, Type 0 fonts that use a CMap whose CIDSystemInfo
        // dictionary defines the Adobe-GB1, Adobe-CNS1 Adobe-Japan1, or Adobe-Korea1 character
        // collection can also be substituted." - Adobe Supplement to the ISO 32000
        String collection = (cidSystemInfo.getRegistry() + "-") + cidSystemInfo.getOrdering();
        if (((collection.equals("Adobe-GB1") || collection.equals("Adobe-CNS1")) || collection.equals("Adobe-Japan1")) || collection.equals("Adobe-Korea1")) {
            // try automatic substitutes via character collection
            PriorityQueue<FontMatch> queue = getFontMatches(fontDescriptor, cidSystemInfo);
            FontMatch bestMatch = queue.poll();
            if (bestMatch != null) {
                if (LOG.isDebugEnabled()) {
                    LOG.debug((("Best match for '" + baseFont) + "': ") + bestMatch.info);
                }
                FontBoxFont font = bestMatch.info.getFont();
                if (font instanceof OpenTypeFont) {
                    return new CIDFontMapping(((OpenTypeFont) (font)), null, true);
                } else if (font != null) {
                    return new CIDFontMapping(null, font, true);
                }
            }
        }
    }
    // last-resort fallback
    return new CIDFontMapping(null, lastResortFont, true);
}

/**
 * Finds a font with the given PostScript name, or a suitable substitute, or null.
 *
 * @param postScriptName
 * 		PostScript font name
 */
private FontBoxFont findFont(FontFormat format, String postScriptName) {
    // handle damaged PDFs, see PDFBOX-2884
    if (postScriptName == null) {
        return null;
    }
    // make sure the font provider is initialized
    if (fontProvider == null) // PATH: Test should invoke the next FontMapperImpl.getProvider(...) [step in execution path]
    {
        getProvider();
    }
    // first try to match the PostScript name
    FontInfo info = getFont(format, postScriptName);
    if (info != null) {
        return info.getFont();
    }
    // remove hyphens (e.g. Arial-Black -> ArialBlack)
    info = getFont(format, postScriptName.replace("-", ""));
    if (info != null) {
        return info.getFont();
    }
    // then try named substitutes
    for (String substituteName : getSubstitutes(postScriptName)) {
        info = getFont(format, substituteName);
        if (info != null) {
            return info.getFont();
        }
    }
    // then try converting Windows names e.g. (ArialNarrow,Bold) -> (ArialNarrow-Bold)
    info = getFont(format, postScriptName.replace(",", "-"));
    if (info != null) {
        return info.getFont();
    }
    if (postScriptName.contains(",")) {
        postScriptName = postScriptName.substring(0, postScriptName.indexOf(","));
        // PDFBOX-5806: try cutting font style and getting the basefont
        // eg. for "Wingdings,Bolt" to "Wingding-Regular" (including the following step)
        info = getFont(format, postScriptName);
        if (info != null) {
            return info.getFont();
        }
    }
    // try appending "-Regular", works for Wingdings on windows
    info = getFont(format, postScriptName + "-Regular");
