@Override
List<ShadedTriangle> collectTriangles(AffineTransform xform, Matrix matrix) throws IOException {
    int bitsPerFlag = getBitsPerFlag();
    COSDictionary dict = getCOSObject();
    if (!(dict instanceof COSStream)) {
        return Collections.emptyList();
    }
    PDRange rangeX = getDecodeForParameter(0);
    PDRange rangeY = getDecodeForParameter(1);
    if ((((rangeX == null) || (rangeY == null)) || (Float.compare(rangeX.getMin(), rangeX.getMax()) == 0)) || (Float.compare(rangeY.getMin(), rangeY.getMax()) == 0)) {
        return Collections.emptyList();
    }
    PDRange[] colRange = new PDRange[getNumberOfColorComponents()];
    for (int i = 0; i < colRange.length; ++i) {
        colRange[i] = getDecodeForParameter(2 + i);
        if (colRange[i] == null) {
            throw new IOException("Range missing in shading /Decode entry");
        }
    }
    List<ShadedTriangle> list = new ArrayList<>();
    long maxSrcCoord = ((long) (Math.pow(2, getBitsPerCoordinate()))) - 1;
    long maxSrcColor = ((long) (Math.pow(2, getBitsPerComponent()))) - 1;
    // MemoryCacheImageInputStream doesn't close the wrapped stream
    try (InputStream imageStream = ((COSStream) (dict)).createInputStream()) {
        try (ImageInputStream mciis = new MemoryCacheImageInputStream(imageStream)) {
            byte flag = ((byte) (0));
            try {
                flag = ((byte) (mciis.readBits(bitsPerFlag) & 3));
            } catch (EOFException ex) {
                LOG.error(ex);
            }
            boolean eof = false;
            while (!eof) {
                Vertex p0;
                Vertex p1;
                Vertex p2;
                Point2D[] ps;
                float[][] cs;
                int lastIndex;
                try {
                    switch (flag) {
                        case 0 :
                            // PATH: Test should invoke the next PDTriangleBasedShadingType.readVertex(...) [step in execution path]
                            p0 = readVertex(mciis, maxSrcCoord, maxSrcColor, rangeX, rangeY, colRange, matrix, xform);
                            flag = ((byte) (mciis.readBits(bitsPerFlag) & 3));
                            if (flag != 0) {
                                LOG.error("bad triangle: " + flag);
                            }
                            p1 = readVertex(mciis, maxSrcCoord, maxSrcColor, rangeX, rangeY, colRange, matrix, xform);
                            mciis.readBits(bitsPerFlag);
                            if (flag != 0) {
                                LOG.error("bad triangle: " + flag);
                            }
                            p2 = readVertex(mciis, maxSrcCoord, maxSrcColor, rangeX, rangeY, colRange, matrix, xform);
                            ps = new Point2D[]{ p0.point, p1.point, p2.point };
                            cs = new float[][]{ p0.color, p1.color, p2.color };
                            list.add(new ShadedTriangle(ps, cs));
                            flag = ((byte) (mciis.readBits(bitsPerFlag) & 3));
                            break;
                        case 1 :
                        case 2 :
                            lastIndex = list.size() - 1;
                            if (lastIndex < 0) {
                                LOG.error(("broken data stream: " + list.size()) + ", aborting");
                                eof = true;
                            } else {
                                ShadedTriangle preTri = list.get(lastIndex);
                                p2 = readVertex(mciis, maxSrcCoord, maxSrcColor, rangeX, rangeY, colRange, matrix, xform);
                                ps = new Point2D[]{ flag == 1 ? preTri.corner[1] : preTri.corner[0], preTri.corner[2], p2.point };
                                cs = new float[][]{ flag == 1 ? preTri.color[1] : preTri.color[0], preTri.color[2], p2.color };
                                list.add(new ShadedTriangle(ps, cs));
                                flag = ((byte) (mciis.readBits(bitsPerFlag) & 3));
                            }
                            break;
                        default :
                            LOG.error(("bad flag " + flag) + ", aborting");
                            eof = true;
                            break;
                    }
                } catch (EOFException ex) {
                    eof = true;
                }
            } 
        }
    }
    return list;
}

/**
 * Read a vertex from the bit input stream performs interpolations.
 *
 * @param input
 * 		bit input stream
 * @param maxSrcCoord
 * 		max value for source coordinate (2^bits-1)
 * @param maxSrcColor
 * 		max value for source color (2^bits-1)
 * @param rangeX
 * 		dest range for X
 * @param rangeY
 * 		dest range for Y
 * @param colRangeTab
 * 		dest range array for colors
 * @param matrix
 * 		the pattern matrix concatenated with that of the parent content stream
 * @param xform
 * 		the affine transformation
 * @return a new vertex with the flag and the interpolated values
 * @throws IOException
 * 		if something went wrong
 */
protected Vertex readVertex(ImageInputStream input, long maxSrcCoord, long maxSrcColor, PDRange rangeX, PDRange rangeY, PDRange[] colRangeTab, Matrix matrix, AffineTransform xform) throws IOException // PATH: Test should invoke the next Log.debug(...) [step in execution path]
{
    if (((bitsPerCoordinate <= 0) || (numberOfColorComponents <= 0)) || (bitsPerColorComponent <= 0)) {
        throw new IOException("nothing to read, check bitsPerCoordinate, numberOfColorComponents and bitsPerColorComponent");
    }
    float[] colorComponentTab = new float[numberOfColorComponents];
    long x = input.readBits(bitsPerCoordinate);
    long y = input.readBits(bitsPerCoordinate);
    float dstX = interpolate(x, maxSrcCoord, rangeX.getMin(), rangeX.getMax());
    float dstY = interpolate(y, maxSrcCoord, rangeY.getMin(), rangeY.getMax());
    LOG.debug("coord: " + String.format("[%06X,%06X] -> [%f,%f]", x, y, dstX, dstY));
    Point2D p = matrix.transformPoint(dstX, dstY);
    xform.transform(p, p);
    for (int n = 0; n < numberOfColorComponents; ++n) {
        int color = ((int) (input.readBits(bitsPerColorComponent)));
        colorComponentTab[n] = interpolate(color, maxSrcColor, colRangeTab[n].getMin(), colRangeTab[n].getMax());
        LOG.debug((((((((("color[" + n) + "]: ") + color) + "/") + String.format("%02x", color)) + "-> color[") + n) + "]: ") + colorComponentTab[n]);
    }
    // "Each set of vertex data shall occupy a whole number of bytes.
    // If the total number of bits required is not divisible by 8, the last data byte
    // for each vertex is padded at the end with extra bits, which shall be ignored."
    int bitOffset = input.getBitOffset();
    if (bitOffset != 0) {
        input.readBits(8 - bitOffset);
    }
    return new Vertex(p, colorComponentTab);
}

