@Override
public void process(Operator operator, List<COSBase> operands) throws IOException // PATH: Test should invoke the next PageDrawer.shadingFill(...) [step in execution path]
{
    if (operands.isEmpty()) {
        throw new MissingOperandException(operator, operands);
    }
    COSBase base = operands.get(0);
    if (!(base instanceof COSName)) {
        throw new MissingOperandException(operator, operands);
    }
    getGraphicsContext().shadingFill(((COSName) (base)));
}

@Override
public void shadingFill(COSName shadingName) throws IOException {
    if (!isContentRendered()) {
        return;
    }
    PDShading shading = getResources().getShading(shadingName);
    if (shading == null) {
        LOG.error(("shading " + shadingName) + " does not exist in resources dictionary");
        return;
    }
    Matrix ctm = getGraphicsState().getCurrentTransformationMatrix();
    graphics.setComposite(getGraphicsState().getNonStrokingJavaComposite());
    Shape savedClip = graphics.getClip();
    graphics.setClip(null);
    lastClips = null;
    // get the transformed BBox and intersect with current clipping path
    // need to do it here and not in shading getRaster() because it may have been rotated
    PDRectangle bbox = shading.getBBox();
    Area area;
    if (bbox != null) {
        area = new Area(bbox.transform(ctm));
        area.intersect(getGraphicsState().getCurrentClippingPath());
    } else {
        // PATH: Test should invoke the next PDShadingType5.getBounds(...) [step in execution path]
        Rectangle2D bounds = shading.getBounds(new AffineTransform(), ctm);
        if (bounds != null) {
            bounds.add(new Point2D.Double(Math.floor(bounds.getMinX() - 1), Math.floor(bounds.getMinY() - 1)));
            bounds.add(new Point2D.Double(Math.ceil(bounds.getMaxX() + 1), Math.ceil(bounds.getMaxY() + 1)));
            area = new Area(bounds);
            area.intersect(getGraphicsState().getCurrentClippingPath());
        } else {
            area = getGraphicsState().getCurrentClippingPath();
        }
    }
    if (!area.isEmpty()) {
        // creating Paint is sometimes a costly operation, so avoid if possible
        Paint paint = shading.toPaint(ctm);
        paint = applySoftMaskToPaint(paint, getGraphicsState().getSoftMask());
        graphics.setPaint(paint);
        graphics.fill(area);
    }
    graphics.setClip(savedClip);
}

@Override
public Rectangle2D getBounds(AffineTransform xform, Matrix matrix) throws IOException {
    Rectangle2D bounds = null;
    // PATH: Test should invoke the next PDShadingType5.collectTriangles(...) [step in execution path]
    for (ShadedTriangle shadedTriangle : collectTriangles(xform, matrix)) {
        if (bounds == null) {
            bounds = new Rectangle2D.Double(shadedTriangle.corner[0].getX(), shadedTriangle.corner[0].getY(), 0, 0);
        }
        bounds.add(shadedTriangle.corner[0]);
        bounds.add(shadedTriangle.corner[1]);
        bounds.add(shadedTriangle.corner[2]);
    }
    if (bounds == null) {
        // Speeds up files where triangles are empty, e.g. ghostscript file 690425
        return new Rectangle2D.Float();
    }
    return bounds;
}

@SuppressWarnings("squid:S1166")
@Override
List<ShadedTriangle> collectTriangles(AffineTransform xform, Matrix matrix) throws IOException {
    COSDictionary dict = getCOSObject();
    if (!(dict instanceof COSStream)) {
        return Collections.emptyList();
    }
    PDRange rangeX = getDecodeForParameter(0);
