/**
 * Read a vertex from the bit input stream performs interpolations.
 *
 * @param input
 * 		bit input stream
 * @param maxSrcCoord
 * 		max value for source coordinate (2^bits-1)
 * @param maxSrcColor
 * 		max value for source color (2^bits-1)
 * @param rangeX
 * 		dest range for X
 * @param rangeY
 * 		dest range for Y
 * @param colRangeTab
 * 		dest range array for colors
 * @param matrix
 * 		the pattern matrix concatenated with that of the parent content stream
 * @param xform
 * 		the affine transformation
 * @return a new vertex with the flag and the interpolated values
 * @throws IOException
 * 		if something went wrong
 */
protected Vertex readVertex(ImageInputStream input, long maxSrcCoord, long maxSrcColor, PDRange rangeX, PDRange rangeY, PDRange[] colRangeTab, Matrix matrix, AffineTransform xform) throws IOException {
    if (((bitsPerCoordinate <= 0) || (numberOfColorComponents <= 0)) || (bitsPerColorComponent <= 0)) {
        throw new IOException("nothing to read, check bitsPerCoordinate, numberOfColorComponents and bitsPerColorComponent");
    }
    float[] colorComponentTab = new float[numberOfColorComponents];
    long x = input.readBits(bitsPerCoordinate);
    long y = input.readBits(bitsPerCoordinate);
    float dstX = interpolate(x, maxSrcCoord, rangeX.getMin(), rangeX.getMax());
    float dstY = interpolate(y, maxSrcCoord, rangeY.getMin(), rangeY.getMax());
    LOG.debug("coord: " + String.format("[%06X,%06X] -> [%f,%f]", x, y, dstX, dstY));
    Point2D p = matrix.transformPoint(dstX, dstY);
    xform.transform(p, p);
    for (int n = 0; n < numberOfColorComponents; ++n) {
        int color = ((int) (input.readBits(bitsPerColorComponent)));
        colorComponentTab[n] = interpolate(color, maxSrcColor, colRangeTab[n].getMin(), colRangeTab[n].getMax());
        LOG.debug((((((((("color[" + n) + "]: ") + color) + "/") + String.format("%02x", color)) + "-> color[") + n) + "]: ") + colorComponentTab[n]);
    }
    // "Each set of vertex data shall occupy a whole number of bytes.
    // If the total number of bits required is not divisible by 8, the last data byte
    // for each vertex is padded at the end with extra bits, which shall be ignored."
    int bitOffset = input.getBitOffset();
    if (bitOffset != 0) {
        input.readBits(8 - bitOffset);
    }
    return new Vertex(p, colorComponentTab);
}

