 */
private void processAppearanceStringOperators(byte[] content) throws IOException {
    List<COSBase> arguments = new ArrayList<>();
    PDFStreamParser parser = new PDFStreamParser(content);
    Object token = parser.parseNextToken();
    while (token != null) {
        if (token instanceof Operator) // PATH: Test should invoke the next PDDefaultAppearanceString.processOperator(...) [step in execution path]
        {
            processOperator(((Operator) (token)), arguments);
            arguments = new ArrayList<>();
        } else {
