private void processOperator(Operator operator, List<COSBase> operands) throws IOException {
    switch (operator.getName()) {
        // PATH: Test should invoke the next PDDefaultAppearanceString.processSetFont(...) [step in execution path]
        case OperatorName.SET_FONT_AND_SIZE :
            processSetFont(operands);
            break;
        case OperatorName.NON_STROKING_GRAY :
        case OperatorName.NON_STROKING_RGB :
        case OperatorName.NON_STROKING_CMYK :
            processSetFontColor(operands);
            break;
        default :
            break;
    }
}

/**
 * Process the set font and font size operator.
 *
 * @param operands
 * 		the font name and size
 * @throws IOException
 * 		in case there are missing operators or the font is not within the resources
 */
private void processSetFont(List<COSBase> operands) throws IOException {
    if (operands.size() < 2) {
        throw new IOException("Missing operands for set font operator " + Arrays.toString(operands.toArray()));
    }
    COSBase base0 = operands.get(0);
    COSBase base1 = operands.get(1);
    if (!(base0 instanceof COSName)) {
        return;
    }
    if (!(base1 instanceof COSNumber)) {
        return;
    }
    COSName fontName = ((COSName) (base0));
    // PATH: Test should invoke the next PDResources.getFont(...) [step in execution path]
    PDFont font = defaultResources.getFont(fontName);
    float fontSize = ((COSNumber) (base1)).floatValue();
    // todo: handle cases where font == null with special mapping logic (see PDFBOX-2661)
    if (font == null) {
        throw new IOException("Could not find font: /" + fontName.getName());
    }
    setFontName(fontName);
    setFont(font);
    setFontSize(fontSize);
}

/**
 * Returns the font resource with the given name, or null if none exists.
 *
 * @param name
 * 		Name of the font resource.
 * @return the font with the given name or null
 * @throws IOException
 * 		if something went wrong.
 */
public PDFont getFont(COSName name) throws IOException {
    COSObject indirect = getIndirect(COSName.FONT, name);
    if ((cache != null) && (indirect != null)) {
        PDFont cached = cache.getFont(indirect);
        if (cached != null) {
            return cached;
        }
    } else if (indirect == null) {
        SoftReference<PDFont> ref = directFontCache.get(name);
        if (ref != null) {
            PDFont cached = ref.get();
            if (cached != null) {
                return cached;
            }
        }
    }
    PDFont font = null;
    COSBase base = get(COSName.FONT, name);
    if (base instanceof COSDictionary) {
        // PATH: Test should invoke the next PDFontFactory.createFont(...) [step in execution path]
        font = PDFontFactory.createFont(((COSDictionary) (base)), cache);
    }
    if ((cache != null) && (indirect != null)) {
        cache.put(indirect, font);
    } else if (indirect == null) {
        directFontCache.put(name, new SoftReference<>(font));
    }
    return font;
}

/**
 * Creates a new PDFont instance with the appropriate subclass.
 *
 * @param dictionary
 * 		a font dictionary
 * @param resourceCache
 * 		resource cache, only useful for type 3 fonts, can be null
 * @return a PDFont instance, based on the SubType entry of the dictionary
 * @throws IOException
 * 		if something goes wrong
 */
public static PDFont createFont(COSDictionary dictionary, ResourceCache resourceCache) throws IOException {
    COSName type = dictionary.getCOSName(COSName.TYPE, COSName.FONT);
    if (!COSName.FONT.equals(type)) {
        LOG.error(("Expected 'Font' dictionary but found '" + type.getName()) + "'");
    }
    COSName subType = dictionary.getCOSName(COSName.SUBTYPE);
    if (COSName.TYPE1.equals(subType)) {
        COSDictionary fd = dictionary.getCOSDictionary(COSName.FONT_DESC);
        if ((fd != null) && fd.containsKey(COSName.FONT_FILE3)) {
            return new PDType1CFont(dictionary);
        }
        return new PDType1Font(dictionary);
    } else if (COSName.MM_TYPE1.equals(subType)) {
        COSDictionary fd = dictionary.getCOSDictionary(COSName.FONT_DESC);
        if ((fd != null) && fd.containsKey(COSName.FONT_FILE3)) {
            return new PDType1CFont(dictionary);
        }
        return new PDMMType1Font(dictionary);
    } else if (COSName.TRUE_TYPE.equals(subType)) {
        return new PDTrueTypeFont(dictionary);
    } else if (COSName.TYPE3.equals(subType)) {
        return new PDType3Font(dictionary, resourceCache);
    } else if (COSName.TYPE0.equals(subType)) {
        COSDictionary fontDescriptor = getFontDescriptor(dictionary);
        FontType fontTypeFromFont = getFontTypeFromFont(fontDescriptor, subType);
        if (fontTypeFromFont != null) {
            COSDictionary descendantFont = getDescendantFont(dictionary);
            COSName descFontType = (descendantFont != null) ? descendantFont.getCOSName(COSName.SUBTYPE) : null;
            if ((descFontType != null) && (!fontTypeFromFont.isCIDSubtype(descFontType))) {
                fixType0Subtype(descendantFont, fontDescriptor, fontTypeFromFont.getSubtype());
            }
        }
        return new PDType0Font(dictionary);
    } else if (COSName.CID_FONT_TYPE0.equals(subType)) {
        throw new IOException("Type 0 descendant font not allowed");
    } else if (COSName.CID_FONT_TYPE2.equals(subType)) {
        throw new IOException("Type 2 descendant font not allowed");
    } else {
        // assuming Type 1 font (see PDFBOX-1988) because it seems that Adobe Reader does this
        // however, we may need more sophisticated logic perhaps looking at the FontFile
        LOG.warn(("Invalid font subtype '" + subType) + "'");
        return new PDType1Font(dictionary);
    }
}

/**
