    TrueTypeFont ttf = ((TrueTypeFont) (findFont(FontFormat.TTF, postScriptName)));
    if (ttf != null) {
        return ttf;
    }
    OpenTypeFont otf = ((OpenTypeFont) (findFont(FontFormat.OTF, postScriptName)));
    if (otf != null) {
