/**
 * Creates a new PDFont instance with the appropriate subclass.
 *
 * @param dictionary
 * 		a font dictionary
 * @param resourceCache
 * 		resource cache, only useful for type 3 fonts, can be null
 * @return a PDFont instance, based on the SubType entry of the dictionary
 * @throws IOException
 * 		if something goes wrong
 */
public static PDFont createFont(COSDictionary dictionary, ResourceCache resourceCache) throws IOException {
    COSName type = dictionary.getCOSName(COSName.TYPE, COSName.FONT);
    if (!COSName.FONT.equals(type)) {
        LOG.error(("Expected 'Font' dictionary but found '" + type.getName()) + "'");
    }
    COSName subType = dictionary.getCOSName(COSName.SUBTYPE);
    if (COSName.TYPE1.equals(subType)) {
        COSDictionary fd = dictionary.getCOSDictionary(COSName.FONT_DESC);
        if ((fd != null) && fd.containsKey(COSName.FONT_FILE3)) {
            return new PDType1CFont(dictionary);
        }
        return new PDType1Font(dictionary);
    } else if (COSName.MM_TYPE1.equals(subType)) {
        COSDictionary fd = dictionary.getCOSDictionary(COSName.FONT_DESC);
        if ((fd != null) && fd.containsKey(COSName.FONT_FILE3)) {
            return new PDType1CFont(dictionary);
        }
        return new PDMMType1Font(dictionary);
    } else if (COSName.TRUE_TYPE.equals(subType)) {
        return new PDTrueTypeFont(dictionary);
    } else if (COSName.TYPE3.equals(subType)) {
        return new PDType3Font(dictionary, resourceCache);
    } else if (COSName.TYPE0.equals(subType)) {
        COSDictionary fontDescriptor = getFontDescriptor(dictionary);
        FontType fontTypeFromFont = getFontTypeFromFont(fontDescriptor, subType);
        if (fontTypeFromFont != null) {
            COSDictionary descendantFont = getDescendantFont(dictionary);
            COSName descFontType = (descendantFont != null) ? descendantFont.getCOSName(COSName.SUBTYPE) : null;
            if ((descFontType != null) && (!fontTypeFromFont.isCIDSubtype(descFontType))) {
                fixType0Subtype(descendantFont, fontDescriptor, fontTypeFromFont.getSubtype());
            }
        }
        return new PDType0Font(dictionary);
    } else if (COSName.CID_FONT_TYPE0.equals(subType)) {
        throw new IOException("Type 0 descendant font not allowed");
    } else if (COSName.CID_FONT_TYPE2.equals(subType)) {
        throw new IOException("Type 2 descendant font not allowed");
    } else {
        // assuming Type 1 font (see PDFBOX-1988) because it seems that Adobe Reader does this
        // however, we may need more sophisticated logic perhaps looking at the FontFile
        LOG.warn(("Invalid font subtype '" + subType) + "'");
        return new PDType1Font(dictionary);
    }
}

/**
 * Constructor.
 *
 * @param fontDictionary
 * 		the corresponding dictionary
 * @throws IOException
 * 		it something went wrong
 */
public (COSDictionary fontDictionary) throws IOException {
    this(fontDictionary);
    boolean fontIsDamaged = false;
    CFFType1Font cffEmbedded = null;
    PDFontDescriptor fd = getFontDescriptor();
    if (fd != null) {
        PDStream ff3Stream = fd.getFontFile3();
        if (ff3Stream != null) {
            try (RandomAccessRead randomAccessRead = ff3Stream.getCOSObject().createView()) {
                if (randomAccessRead.length() == 0) {
                    LOG.error("Invalid data for embedded Type1C font " + getName());
                } else {
                    // note: this could be an OpenType file, fortunately CFFParser can handle that
                    CFFParser cffParser = new CFFParser();
                    CFFFont parsedCffFont = cffParser.parse(randomAccessRead).get(0);
                    if (parsedCffFont instanceof CFFType1Font) {
                        cffEmbedded = ((CFFType1Font) (parsedCffFont));
                    } else {
                        LOG.error("Expected CFFType1Font, got " + parsedCffFont.getClass().getSimpleName());
                        fontIsDamaged = true;
                    }
                }
            } catch (IOException e) {
                LOG.error("Can't read the embedded Type1C font " + getName(), e);
                fontIsDamaged = true;
            }
        }
    }
    isDamaged = fontIsDamaged;
    cffFont = cffEmbedded;
    if (cffFont != null) {
        genericFont = cffFont;
        isEmbedded = true;
    } else {
        String baseFont = getBaseFont();
        // PATH: Test should invoke the next FontMapperImpl.getFontBoxFont(...) [step in execution path]
        FontMapping<FontBoxFont> mapping = FontMappers.instance().getFontBoxFont(baseFont, fd);
        genericFont = mapping.getFont();
        if (mapping.isFallback()) {
            LOG.warn((("Using fallback font " + genericFont.getName()) + " for ") + baseFont);
        }
        isEmbedded = false;
    }
    readEncoding();
    fontMatrixTransform = getFontMatrix().createAffineTransform();
    fontMatrixTransform.scale(1000, 1000);
}

/**
 * Finds a font with the given PostScript name, or a suitable substitute, or null. This allows
 * any font to be substituted with a PFB, TTF or OTF.
 *
 * @param fontDescriptor
 * 		the FontDescriptor of the font to find
 */
@Override
public FontMapping<FontBoxFont> getFontBoxFont(String baseFont, PDFontDescriptor fontDescriptor) {
    // PATH: Test should invoke the next FontMapperImpl.findFontBoxFont(...) [step in execution path]
    FontBoxFont font = findFontBoxFont(baseFont);
    if (font != null) {
        return new FontMapping<>(font, false);
    } else {
        // fallback - todo: i.e. fuzzy match
        String fallbackName = getFallbackFontName(fontDescriptor);
        font = findFontBoxFont(fallbackName);
        if (font == null) {
            // we have to return something here as TTFs aren't strictly required on the system
            font = lastResortFont;
        }
        return new FontMapping<>(font, true);
    }
}

/**
 * Finds a font with the given PostScript name, or a suitable substitute, or null.
 *
 * @param postScriptName
 * 		PostScript font name
 */
private FontBoxFont findFontBoxFont(String postScriptName) {
    // PATH: Test should invoke the next FontMapperImpl.findFont(...) [step in execution path]
    Type1Font t1 = ((Type1Font) (findFont(FontFormat.PFB, postScriptName)));
    if (t1 != null) {
        return t1;
    }
    TrueTypeFont ttf = ((TrueTypeFont) (findFont(FontFormat.TTF, postScriptName)));
    if (ttf != null) {
        return ttf;
    }
    OpenTypeFont otf = ((OpenTypeFont) (findFont(FontFormat.OTF, postScriptName)));
    if (otf != null) {
        return otf;
    }
    return null;
}

/**
 * Finds a font with the given PostScript name, or a suitable substitute, or null.
 *
 * @param postScriptName
 * 		PostScript font name
 */
private FontBoxFont findFont(FontFormat format, String postScriptName) {
    // handle damaged PDFs, see PDFBOX-2884
    if (postScriptName == null) {
        return null;
    }
    // make sure the font provider is initialized
    if (fontProvider == null) // PATH: Test should invoke the next FontMapperImpl.getProvider(...) [step in execution path]
    {
        getProvider();
    }
    // first try to match the PostScript name
    FontInfo info = getFont(format, postScriptName);
    if (info != null) {
        return info.getFont();
    }
    // remove hyphens (e.g. Arial-Black -> ArialBlack)
    info = getFont(format, postScriptName.replace("-", ""));
    if (info != null) {
        return info.getFont();
    }
    // then try named substitutes
    for (String substituteName : getSubstitutes(postScriptName)) {
        info = getFont(format, substituteName);
        if (info != null) {
            return info.getFont();
        }
    }
    // then try converting Windows names e.g. (ArialNarrow,Bold) -> (ArialNarrow-Bold)
    info = getFont(format, postScriptName.replace(",", "-"));
    if (info != null) {
        return info.getFont();
    }
    if (postScriptName.contains(",")) {
        postScriptName = postScriptName.substring(0, postScriptName.indexOf(","));
        // PDFBOX-5806: try cutting font style and getting the basefont
        // eg. for "Wingdings,Bolt" to "Wingding-Regular" (including the following step)
        info = getFont(format, postScriptName);
        if (info != null) {
            return info.getFont();
        }
    }
    // try appending "-Regular", works for Wingdings on windows
    info = getFont(format, postScriptName + "-Regular");
    if (info != null) {
        return info.getFont();
    }
    // no matches
    return null;
}

/**
 * Returns the font service provider. Defaults to using FileSystemFontProvider.
 */
public synchronized FontProvider getProvider() {
    if (fontProvider == null) {
        setProvider(DefaultFontProvider.INSTANCE);
    }
    return fontProvider;
}

