    addSubstitutes("Times-Roman", new ArrayList<>(Arrays.asList("TimesNewRomanPSMT", "TimesNewRoman", "TimesNewRomanPS", "LiberationSerif", "NimbusRomNo9L-Regu")));
    addSubstitutes("Times-Bold", new ArrayList<>(Arrays.asList("TimesNewRomanPS-BoldMT", "TimesNewRomanPS-Bold", "TimesNewRoman-Bold", "LiberationSerif-Bold", "NimbusRomNo9L-Medi")));
    addSubstitutes("Times-Italic", new ArrayList<>(Arrays.asList("TimesNewRomanPS-ItalicMT", "TimesNewRomanPS-Italic", "TimesNewRoman-Italic", "LiberationSerif-Italic", "NimbusRomNo9L-ReguItal")));
    addSubstitutes("Times-BoldItalic", new ArrayList<>(Arrays.asList("TimesNewRomanPS-BoldItalicMT", "TimesNewRomanPS-BoldItalic", "TimesNewRoman-BoldItalic", "LiberationSerif-BoldItalic", "NimbusRomNo9L-MediItal")));
    addSubstitutes("Symbol", new ArrayList<>(Arrays.asList("Symbol", "SymbolMT", "StandardSymL")));
    addSubstitutes("ZapfDingbats", new ArrayList<>(Arrays.asList("ZapfDingbatsITCbyBT-Regular", "ZapfDingbatsITC", "Dingbats", "MS-Gothic", "DejaVuSans")));
    // Acrobat also uses alternative names for Standard 14 fonts, which we map to those above
    // these include names such as "Arial" and "TimesNewRoman"
    for (String baseName : Standard14Fonts.getNames()) {
        if (getSubstitutes(baseName).isEmpty()) {
            FontName mappedName = Standard14Fonts.getMappedFontName(baseName);
            addSubstitutes(baseName, new ArrayList<>(getSubstitutes(mappedName.getName())));
        }
    }
    // -------------------------
    try {
        String resourceName = "/org/apache/pdfbox/resources/ttf/LiberationSans-Regular.ttf";
        InputStream resourceAsStream = FontMapper.class.getResourceAsStream(resourceName);
        if (resourceAsStream == null) {
            throw new IOException(("resource '" + resourceName) + "' not found");
        }
        RandomAccessReadBuffer randomAccessReadBuffer = RandomAccessReadBuffer.createBufferFromStream(resourceAsStream);
        TTFParser ttfParser = new TTFParser();
        lastResortFont = ttfParser.parse(randomAccessReadBuffer);
    } catch (IOException e) {
        throw new RuntimeException(e);
    }
}

